entries[41443] = { ["name"] = "Kessel des erheblichen Arkanschutzes", ["text"] = "Wirken in 3 sek.\nStellt einen Kessel her, der von anderen Schlachtzugsmitgliedern benutzt werden kann, um einen erheblichen Arkanschutztrank herbeizuzaubern. Der Kessel enthält 25 Anwendungen und bleibt 5 min lang bestehen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
