entries[41604] = { ["name"] = "Oberste Macht von Shattrath", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Zaubermacht 1 hour lang um 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41605] = { ["name"] = "Mächtige Wiederherstellung von Shattrath", ["text"] = "Sofort\nErhöht die Manaregeneration des Spielers 1 hour lang um 31 Mana alle 5 Sekunden. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41606] = { ["name"] = "Unerbittlicher Angriff von Shattrath", ["text"] = "Sofort\nErhöht 1 hour lang die Angriffskraft um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41607] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht die maximale Gesundheit des Spielers 1 hour lang um 500 und die Verteidigungswertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41608] = { ["name"] = "Unerbittlicher Angriff von Shattrath", ["text"] = "Sofort\nErhöht die Angriffskraft 1 hour lang um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
entries[41609] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht die maximale Gesundheit 1 hour lang um 500 und die Verteidigungswertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
entries[41610] = { ["name"] = "Mächtige Wiederherstellung von Shattrath", ["text"] = "Sofort\nErhöht die Manaregeneration 1 hour lang um 31 Mana alle 5 Sekunden. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
entries[41611] = { ["name"] = "Oberste Macht von Shattrath", ["text"] = "Sofort\nErhöht die Schadenswirkung von Zaubern und magischen Effekten 1 hour lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
